# Initially generated by GitHub Copilot.
"""
Check that every Hebrew word in tracked .py and .json files has the
project’s standard combining-mark order (SBL2):

    base letter → shin/sin dot → dagesh → rafeh → (everything else unchanged)

The canonical reordering function is ``give_std_mark_order`` from
mb_cmn.uni_denorm.

A “Hebrew word” is any maximal run matched by the regex:

    WORD_RE = r"[\\u0590-\\u05FF\\u034F\\uFB1E]+"

i.e. one or more characters from the Hebrew block (U+0590–U+05FF),
plus Combining Grapheme Joiner (U+034F) and Varika (U+FB1E).  Words that
contain no Hebrew *letter* (U+05D0–U+05EA) are skipped.

Exit codes:
  0 – All files pass
  1 – One or more violations found
"""

import re
import sys

from mb_cmn.uni_denorm import give_std_mark_order

import repo_scopes

# ── regex definitions ────────────────────────────────────────────────────────────────────

# A “Hebrew word”: maximal run of Hebrew-block chars + CGJ + Varika.
WORD_RE = re.compile(r"[\u0590-\u05FF\u034F\uFB1E]+")

# At least one Hebrew letter (alef through tav).
HAS_LETTER_RE = re.compile(r"[\u05D0-\u05EA]")

# ── file discovery ──────────────────────────────────────────────────────────────────────

_SKIP_DIRS = {".venv", "__pycache__", ".novc", ".git", "node_modules"}


def main():
    all_violations = []

    files = sorted(_scoped_files())
    for path in files:
        all_violations.extend(_check_file(path))

    if all_violations:
        print(f"FAIL: {len(all_violations)} word(s) with non-standard mark order:\n")
        for rel, line_no, orig, fixed in all_violations:
            # Show codepoint sequences for clarity.
            orig_cp = " ".join(f"U+{ord(c):04X}" for c in orig)
            fixed_cp = " ".join(f"U+{ord(c):04X}" for c in fixed)
            print(f"  {rel}:{line_no}")
            print(f"    original : {orig}  [{orig_cp}]")
            print(f"    expected : {fixed}  [{fixed_cp}]")
            print()
        return 1

    print(f"OK: all Hebrew words in {len(files)} files have standard mark order.")
    return 0


def _tracked_files(root):
    """Yield .py and .json paths under *root*, skipping non-tracked dirs."""
    for p in sorted(root.rglob("*")):
        if any(part in _SKIP_DIRS for part in p.parts):
            continue
        if p.is_file() and p.suffix in (".py", ".json"):
            yield p


def _scoped_files():
    """Yield the .py and .json of each in-scope repo's code AND of its corpus.

    Scoped rather than repo-wide.  A ``.git`` walk stood here until the code moved
    into MAM-basics, where that walk finds a root holding all of this repo and the
    check has no repo-wide meaning: it reports violations in ``py/ws/`` that are
    nobody's business here.  ``repo_scopes``' module docstring says which repos are
    in and why the corpus list is the shorter of the two.

    BOTH ROOTS, and that is not symmetry for its own sake.  This check reads ``.json``
    as well as ``.py``, and the hand-made ``.json`` stayed in each corpus when the
    Python left -- 24 line-break files under book-of-job's ``py_ac_loc/`` and 78
    line-break, column-coordinate and flat-stream files in codex-index-aleppo.
    Scanning the code alone would have dropped those from the check while it went on
    reporting success, which is how a lint stops meaning anything.
    """
    for entry in repo_scopes.code_paths():
        if entry.is_file():
            if entry.suffix in (".py", ".json"):
                yield entry
        else:
            yield from _tracked_files(entry)
    yield from _corpus_json_files()


def _corpus_json_files():
    """Yield the .json under each in-scope corpus root, skipping non-tracked dirs."""
    for root in repo_scopes.corpus_roots():
        for p in sorted(root.rglob("*.json")):
            if any(part in _SKIP_DIRS for part in p.parts):
                continue
            if p.is_file():
                yield p


# ── checking logic ──────────────────────────────────────────────────────────────────────


def _display_path(path):
    """*path* as a report shows it: relative to whichever in-scope root holds it.

    Several roots and not one, because this check spans them all -- the code under
    this repo's ``py/`` and the corpus in each sibling data repo.  A single
    ``relative_to`` raises ValueError on every file under any of the others.
    """
    for root in repo_scopes.display_roots():
        try:
            return str(path.relative_to(root))
        except ValueError:
            continue
    return str(path)


def _check_file(path):
    """Return list of (rel_path, line_no, original, reordered) tuples."""
    violations = []
    try:
        text = path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError) as exc:
        print(f"  WARNING: could not read {_display_path(path)}: {exc}")
        return violations

    for line_no, line in enumerate(text.splitlines(), 1):
        for m in WORD_RE.finditer(line):
            word = m.group()
            if not HAS_LETTER_RE.search(word):
                continue
            fixed = give_std_mark_order(word)
            if fixed != word:
                violations.append((_display_path(path), line_no, word, fixed))
    return violations


if __name__ == "__main__":
    sys.exit(main())
